{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Untie history-input and target-output embeddings across all four category models, initializing both tables identically with zero padding. Independent contextual and ranking gradients may improve representation under the existing pointwise loss. Frequency attenuation remains exclusive to historical inputs. The predictor writer already imports the updated model class and loads its full state dictionary, preserving checkpoint consistency.",
      "edits": [
        {
          "find": "            nn.init.xavier_uniform_(self.pos_emb.weight)\n            self.pos_emb.weight[0].zero_()\n\n    def encode_sequence",
          "replace": "            nn.init.xavier_uniform_(self.pos_emb.weight)\n            self.pos_emb.weight[0].zero_()\n        self.output_item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)\n        with torch.no_grad():\n            self.output_item_emb.weight.copy_(self.item_emb.weight)\n            self.output_item_emb.weight[0].zero_()\n\n    def encode_sequence"
        },
        {
          "find": "        pos_scores = (out * self.item_emb(pos)).sum(dim=-1)\n        neg_scores = (out * self.item_emb(neg)).sum(dim=-1)",
          "replace": "        pos_scores = (out * self.output_item_emb(pos)).sum(dim=-1)\n        neg_scores = (out * self.output_item_emb(neg)).sum(dim=-1)"
        },
        {
          "find": "        cand_emb = self.item_emb(candidates)",
          "replace": "        cand_emb = self.output_item_emb(candidates)"
        }
      ]
    }
  ],
  "change_summary": "Separate jointly trained input and output item embeddings within each category’s single NextItNet model. Preserve dimensions, features, causal backbone, scoring, loss, optimizer, routing and training limits."
}
